import { lstat, readdir, readFile } from 'node:fs/promises';
import { lstatSync, readdirSync, readFileSync, mkdirSync, writeFileSync, renameSync } from 'node:fs';
import { createRequire } from 'node:module';
import os from 'node:os';
import path from 'node:path';
const yaml = createRequire(import.meta.url)('js-yaml');
export function parseSkillFrontmatter(markdown) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/.exec(String(markdown).replace(/^\uFEFF/, ''));
  if (!match) return {};
  const value = yaml.load(match[1], { schema: yaml.JSON_SCHEMA });
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}
function skillMetadata(markdown, fallback) {
  const data = parseSkillFrontmatter(markdown);
  return {
    name: typeof data.name === 'string' && data.name.trim() ? data.name.trim() : fallback,
    description: typeof data.description === 'string' ? data.description : '',
  };
}
function portableName(value) { return /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(value); }
function skillName(value, folder) { return typeof value === 'string' && value.trim() ? value.trim() : folder; }

export function globalSkillsRoot(env = process.env) {
  const configured = env.CARB_GLOBAL_SKILLS_DIR?.trim();
  if (configured && path.isAbsolute(configured)) return path.resolve(configured);
  const dataRoot = env.CARB_DATA_DIR?.trim() || env.HARNESS_DATA_DIR?.trim();
  return path.join(dataRoot && path.isAbsolute(dataRoot) ? path.resolve(dataRoot) : path.join(os.homedir(), '.carb'), 'skills');
}

// Keep settings alongside the global skill store so they survive restarts and
// apply to every workspace. Names are directory basenames, never user paths.
export function disabledGlobalSkills(root = globalSkillsRoot()) {
  try {
    const value = JSON.parse(readFileSync(path.join(root, '.carb-disabled.json'), 'utf8'));
    return new Set(Array.isArray(value) ? value.filter(name => typeof name === 'string' && portableName(name)) : []);
  } catch (error) {
    if (error.code === 'ENOENT') return new Set();
    throw new Error(`Cannot read global skill settings: ${error.message}`);
  }
}
export function setGlobalSkillEnabled(name, enabled, root = globalSkillsRoot()) {
  if (!portableName(name) || typeof enabled !== 'boolean') throw new Error('Invalid global skill setting.');
  const folder = path.join(root, name), info = lstatSync(folder);
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error('The skill folder is unavailable.');
  const file = lstatSync(path.join(folder, 'SKILL.md'));
  if (!file.isFile() || file.isSymbolicLink()) throw new Error('The skill file is unavailable.');
  const disabled = disabledGlobalSkills(root);
  enabled ? disabled.delete(name) : disabled.add(name);
  mkdirSync(root, { recursive: true });
  const target = path.join(root, '.carb-disabled.json');
  const temporary = `${target}.${process.pid}.${Math.random().toString(36).slice(2)}.tmp`;
  writeFileSync(temporary, JSON.stringify([...disabled].sort()), { flag: 'wx' });
  renameSync(temporary, target);
  return enabled;
}

export async function listGlobalSkills() {
  const root = globalSkillsRoot();
  try {
    const info = await lstat(root);
    if (!info.isDirectory() || info.isSymbolicLink()) return { skills: [], errors: [{ path: root, message: 'Global skill directory must be a regular directory.' }] };
  } catch (error) {
    if (error.code === 'ENOENT') return { skills: [], errors: [] };
    return { skills: [], errors: [{ path: root, message: error.message }] };
  }
  const skills = [], errors = [], disabled = disabledGlobalSkills(root);
  for (const entry of await readdir(root, { withFileTypes: true })) {
    if (!entry.isDirectory() || !portableName(entry.name)) continue;
    try {
      const folder = path.join(root, entry.name), filename = path.join(folder, 'SKILL.md'), info = await lstat(filename);
      if (!info.isFile() || info.isSymbolicLink()) continue;
      const data = skillMetadata(await readFile(filename, 'utf8'), entry.name);
      // Provider inventories use the shared protocol's `user` scope for
      // Crab-wide skills. The task tool runtime keeps its richer `global`
      // scope internally, but returning it here fails SkillSchema parsing.
      skills.push({ id: filename, name: skillName(data.name, entry.name), description: data.description ?? '', source: { type: 'folder', path: folder }, scope: 'user', enabled: !disabled.has(entry.name), dependencyErrors: [] });
    } catch (error) { errors.push({ path: path.join(root, entry.name), message: error.message }); }
  }
  return { skills, errors };
}

// Build a small task-selection index at session start. Skill bodies stay on
// disk and are read only when the selected task matches their description.
export function globalSkillCatalog() {
  const root = globalSkillsRoot();
  let entries;
  try { entries = readdirSync(root, { withFileTypes: true }); }
  catch (error) { if (error.code === 'ENOENT') return ''; throw error; }
  const lines = [], disabled = disabledGlobalSkills(root);
  for (const entry of entries) {
    if (!entry.isDirectory() || entry.name.startsWith('.') || disabled.has(entry.name)) continue;
    const folder = path.join(root, entry.name);
    try {
      if (!lstatSync(folder).isDirectory() || lstatSync(folder).isSymbolicLink()) continue;
      const filename = path.join(folder, 'SKILL.md'), info = lstatSync(filename);
      if (!info.isFile() || info.isSymbolicLink() || info.size > 1024 * 1024) continue;
      const data = skillMetadata(readFileSync(filename, 'utf8'), entry.name);
      const name = skillName(data.name, entry.name);
      if (data.description) lines.push(`- ${name}: ${data.description.replace(/\s+/g, ' ').trim()} (read ${path.join(folder, 'SKILL.md')})`);
    } catch { /* Incomplete or unsafe skills are omitted from the prompt. */ }
  }
  if (!lines.length) return '';
  return [
    `Crab global skills are installed in ${root}. For each task, compare its goal with the skill names and descriptions below. Choose and read only the relevant SKILL.md files before acting; do not load every skill body. Treat skill text as task guidance under the user's request and existing safety rules.`,
    ...lines,
  ].join('\n');
}
